1459	fn hold_step<B, MD>(bot: &mut B, wakeup_ns: i64, cap: i64) -> Result<ElapseResult, B::Error>
1460	where
1461	    B: Bot<MD>,
1462	    MD: MarketDepth,
1463	{
1464	    let step = ON_EVENT_POLL_STEP_NS;
1465	    let now = bot.current_timestamp();
1466	    // Точка сетки ≥ порога, не ближе следующей; и последняя точка сетки строго до конца данных.
1467	    let k_wake = wakeup_ns.saturating_sub(now).div_euclid(step)
1468	        + i64::from(wakeup_ns.saturating_sub(now).rem_euclid(step) != 0);
1469	    let k_cap = (cap.saturating_sub(now) - 1).div_euclid(step);
1470	    let k = k_wake.min(k_cap);
1471	    if k <= 1 {
1472	        return bot.elapse(step);
1473	    }
1474	    let target = now.saturating_add(k.saturating_mul(step));
1475	    HOLD_SKIPS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
1476	    match bot.wait_next_feed(false, target - now)? {
1477	        ElapseResult::MarketFeed => {
1478	            let e = bot.current_timestamp();
1479	            let ke = (e - now).div_euclid(step) + i64::from((e - now).rem_euclid(step) != 0);
1480	            let g = now.saturating_add(ke.max(1).saturating_mul(step));
1481	            bot.elapse(g - e)
1482	        }
1483	        other => Ok(other),
1484	    }
1485	}
1486	
1487	fn run_round<B, MD>(
1488	    bot: &mut B,
1489	    asset_no: usize,
1490	    state: &mut StrategyState,
1491	    entry_id: u64,
1492	    legs: u8,
1493	    side: HbtSide,
1494	    skip_cap: Option<i64>,
1495	) -> Result<(RoundOutcome, f64), B::Error>
1496	where
1497	    B: Bot<MD>,
1498	    MD: MarketDepth,
1499	{
1500	    let mut timed_out = false;
1501	    // Почему вход кончился без позиции (F5, В-74): несётся из `on_event` до
1502	    // `RoundOutcome::TimedOut`, чтобы по кругам формы посчитались снятия по
1503	    // стене, полосе и потолку отдельно.
1504	    let mut cancel_reason = EntryCancelReason::NotPlaced;
1505	    // Путь исполнения входа (F3): `entry_seen` — ноги, исполнение которых уже
1506	    // замечено; `entry_pending` — ноги, чей вердикт (сделка или крест) отложен
1507	    // на шаг (локальная метка сделки отстаёт от биржевой); `fill_by_cross` —
1508	    // итог по кругу. Битовая маска вместо вектора: ног у плана единицы.
1509	    let mut entry_seen: u64 = 0;
1510	    let mut entry_pending: u64 = 0;
1511	    let mut fill_by_cross = false;
1512	    // Ноги выхода в порядке отправки: одна у прежних форм, две у дробных (E7),
1513	    // и больше при доборах остатка моделью очереди по объёму (F4). Третий
1514	    // элемент — заявка несла **часть** позиции (`Action::partial`), а не весь
1515	    // остаток: `n_partial` считает именно доли E7, а не число заявок выхода.
1516	    let mut exits: Vec<(u64, ExitReason, bool)> = Vec::new();
1517	    loop {
1518	        // Э-04б: в удержании без заявок пустые шаги опроса пропускаются (`hold_step`), иначе — шаг 10 мс.
1519	        let wakeup = match skip_cap {
1520	            Some(_) if entry_pending == 0 && !has_open_orders(bot, asset_no) => {
1521	                state.hold_wakeup_ns(bot.current_timestamp())
1522	            }
1523	            _ => None,
1524	        };
1525	        let stepped = match (wakeup, skip_cap) {
1526	            (Some(th), Some(cap)) => hold_step(bot, th, cap)?,
1527	            _ => bot.elapse(ON_EVENT_POLL_STEP_NS)?,
1528	        };
1529	        if stepped == ElapseResult::EndOfData {
1530	            // Хвост записи: круг неполон, `Fill` не строится — вердикт пути
1531	            // исполнения не нужен.
1532	            return Ok((RoundOutcome::EndOfData, state.position()));
1533	        }
1534	        // Отложенный вердикт: буфер за это время дорос сделками следующего
1535	        // шага — если сделка, способная исполнить ногу, появилась, это лента.
1536	        if entry_pending != 0 {
1537	            fill_by_cross |= pending_is_cross(bot, asset_no, entry_id, side, entry_pending, legs);
1538	            entry_pending = 0;
1539	        }
1540	        for i in 0..u32::from(legs.max(1)) {
1541	            if i >= u64::BITS {
1542	                break;
1543	            }
1544	            let bit = 1u64 << i;
1545	            if entry_seen & bit != 0 {
1546	                continue;
1547	            }
1548	            let Some(o) = bot
1549	                .orders(asset_no)
1550	                .get(&entry_id.saturating_add(u64::from(i)))
1551	            else {
1552	                continue;
1553	            };
1554	            // Исполнено — накопленным (`qty − leaves_qty`), а не `exec_qty`:
1555	            // у крейта `exec_qty` — объём **последнего** исполнения, а не сумма.
1556	            if executed_qty(o) <= 0.0 {
1557	                continue;
1558	            }
1559	            entry_seen |= bit;
1560	            let tick = bot.depth(asset_no).tick_size();
1561	            if !trade_could_fill(bot.last_trades(asset_no), side, o.price_tick, tick) {
1562	                // Сделки, способной исполнить ногу, в буфере пока нет: вердикт
1563	                // ждёт шага, чтобы локальная метка сделки догнала биржевое
1564	                // исполнение. Если сделки не будет и на следующем шаге —
1565	                // путь (3), обновление лучшей цены.
1566	                entry_pending |= bit;
1567	            }
1568	        }
1569	        // Буфер нужен только пока есть отложенный вердикт — иначе очищаем
1570	        // (память не растёт с длиной круга). Перед очисткой сделки этого шага
1571	        // отдаются стратегии: F7 (Б-75) считает по ним съеденное в стену, а
1572	        // заново буфер не открывается — считаем ровно один раз на шаг.
1573	        if entry_pending == 0 {
1574	            state.observe_wall_trades(bot.last_trades(asset_no));
1575	            bot.clear_last_trades(Some(asset_no));
1576	        }
1577	        match on_event(bot, state)? {
1578	            Action::EntryTimedOut { reason, .. } => {
1579	                timed_out = true;
1580	                cancel_reason = reason;
1581	            }
1582	            Action::ExitSubmitted {
1583	                order_id,
1584	                reason,
1585	                partial,
1586	                ..
1587	            } => exits.push((order_id, reason, partial)),
1588	            Action::Idle | Action::EntrySubmitted { .. } => {}
1589	        }
1590	        if state.is_idle() {
1591	            break;
1592	        }
1593	    }
1594	    fill_by_cross |= pending_is_cross(bot, asset_no, entry_id, side, entry_pending, legs);
1595	    // Буфер сделок очищается и на выходе из круга: сигналы бывают встык
1596	    // (`t0` не двигает часы), и сделки прошлого круга не должны решать вердикт
1597	    // следующего. Сделки последнего шага перед этим отдаются стратегии (F7).
1598	    state.observe_wall_trades(bot.last_trades(asset_no));
1599	    bot.clear_last_trades(Some(asset_no));
1600	    if timed_out {
1601	        let entry_status = bot.orders(asset_no).get(&entry_id).map(|o| o.status);
1602	        return Ok((
1603	            RoundOutcome::TimedOut {
1604	                entry_status,
1605	                legs_rejected: rejected_legs(bot, asset_no, entry_id, legs),
1606	                reason: cancel_reason,
1607	            },
1608	            state.position(),
1609	        ));
1610	    }
1611	    let Some(&(_, reason, _)) = exits.last() else {
1612	        return Ok((RoundOutcome::Inconsistent, state.position()));
1613	    };
1614	    // Исполненные ноги входа. Отбор — **по факту исполнения** (`exec_qty`), а
1615	    // не по статусу `Filled`: модель очереди по объёму (F3) отдаёт ногу
1616	    // частично исполненной (`PartiallyFilled`), а снятая после частичного
1617	    // исполнения нога — `Canceled` с ненулевым `exec_qty`. У прежней модели
1618	    // (`RiskAdverse`) множество то же: там исполнение всегда целое.
1619	    //
1620	    // Цена входа: `entry_px` — средняя с равными весами (как было: у лестницы
1621	    // ноги равного размера), `entry_vwap` — средневзвешенная по исполненному
1622	    // размеру; при полном исполнении они совпадают, и `roundtrip_net_bps`
1623	    // считает по `entry_vwap` (F3).
1624	    let mut entry_px_sum = 0.0;
1625	    let mut entry_notional = 0.0;
1626	    let mut entry_qty = 0.0;
1627	    let mut entry_legs = 0usize;
1628	    let mut entry_taker = false;
1629	    let mut ordered = 0.0;
1630	    for i in 0..u64::from(legs.max(1)) {
1631	        let Some(o) = bot.orders(asset_no).get(&entry_id.saturating_add(i)) else {
1632	            continue;
1633	        };
1634	        // Заказанное — только принятые биржей ноги: отвергнутая (`Rejected`,
1635	        // `Expired`) нога — отказ, а не заказ, и `fill_frac` из-за неё падать
1636	        // не должен (F4 считает её отдельным счётчиком).
1637	        if !matches!(o.status, Status::Rejected | Status::Expired) {
1638	            ordered += o.qty;
1639	        }
1640	        let exec = executed_qty(o);
1641	        if exec > 0.0 {
1642	            entry_qty += exec;
1643	            // R7: средняя цена ноги — по всем её исполнениям, не цена
1644	            // последнего уровня свипа.
1645	            let notional = executed_notional(o);
1646	            entry_px_sum += notional / exec;
1647	            entry_notional += notional;
1648	            entry_legs += 1;
1649	            // Комиссия ноги — по флагу `maker` ордера крейта (В-63): у
1650	            // лестницы вход тейкерский, если тейкером исполнилась хотя бы одна
1651	            // нога (консервативно).
1652	            entry_taker |= !o.maker;
1653	        }
1654	    }
1655	    let entry_px = if entry_legs == 0 {
1656	        None
1657	    } else {
1658	        Some(entry_px_sum / crate::stats::count_f64(entry_legs))
1659	    };
1660	    let entry_vwap = if entry_qty > 0.0 {
1661	        entry_notional / entry_qty
1662	    } else {
1663	        0.0
1664	    };
1665	    let fill_frac = if ordered > 0.0 {
1666	        entry_qty / ordered
1667	    } else {
1668	        0.0
1669	    };
1670	    // Цена выхода — **средневзвешенная по размеру** исполненных ног (у
1671	    // цельного выхода нога одна — это его же цена); время — последней ноги;
1672	    // комиссия выхода — тейкерская, если тейкером ушла хотя бы одна нога
1673	    // (консервативно, как у лестницы входа).
1674	    let mut exit_qty = 0.0;
1675	    let mut exit_notional = 0.0;
1676	    let mut exit_ts = i64::MIN;
1677	    let mut exit_taker = false;
1678	    for (exit_id, _, _) in &exits {
1679	        if let Some(o) = bot
1680	            .orders(asset_no)
1681	            .get(exit_id)
1682	            .filter(|o| executed_qty(o) > 0.0)
1683	        {
1684	            let exec = executed_qty(o);
1685	            exit_qty += exec;
1686	            exit_notional += executed_notional(o);
1687	            exit_ts = exit_ts.max(o.exch_timestamp);
1688	            exit_taker |= !o.maker;
1689	        }
1690	    }
1691	    // Выход состоялся, если исполненный объём **закрыл вход** — с точностью до
1692	    // шага лота (округление дробного выхода, E7). Заявка выхода, не отдавшая
1693	    // ни лота (маркет-выход в пустой книге — `Expired` у модели очереди по
1694	    // объёму), круг не рассыпает: стратегия шлёт следующую на остаток (F4,
1695	    // В-78), и в `exits` такие ноги остаются. Под полным исполнением
1696	    // (`RiskAdverse`) условие совпадает с прежним «все ноги исполнились», так
1697	    // что числа прежних прогонов не меняются.
1698	    let exit_ok = exit_qty > 0.0 && exit_qty + lot_half(bot.depth(asset_no)) >= entry_qty;
1699	    match (entry_px, exit_ok) {
1700	        (Some(entry_px), true) => {
1701	            let dir = if side == HbtSide::Buy { 1 } else { -1 };
1702	            Ok((
1703	                RoundOutcome::Filled {
1704	                    fill: Fill {
1705	                        dir,
1706	                        entry_px,
1707	                        exit_px: exit_notional / exit_qty,
1708	                        qty: entry_qty,
1709	                        entry_taker,
1710	                        exit_taker,
1711	                        entry_vwap,
1712	                        fill_frac,
1713	                        legs_filled: u8::try_from(entry_legs).unwrap_or(u8::MAX),
1714	                        legs_rejected: rejected_legs(bot, asset_no, entry_id, legs),
1715	                        fill_by_cross,
1716	                    },
1717	                    exit_ts,
1718	                    reason,
1719	                    // Доля отдана, если хоть одна заявка выхода несла часть
1720	                    // позиции (E7). Число заявок о доле не говорит: остаток
1721	                    // добирается новыми заявками (F4).
1722	                    partial: exits.iter().any(|(_, _, partial)| *partial),
1723	                },
1724	                state.position(),
1725	            ))
1726	        }
1727	        _ => Ok((RoundOutcome::Inconsistent, state.position())),
1728	    }
1729	}
1730	
1731	/// Ноги входа, которых биржа **не поставила**: пост-онли заявка (GTX),
1732	/// пересёкшая спред, получает `Expired` в `ack_new` (В-72), отвергнутая —
1733	/// `Rejected`. Такая нога — отказ, а не заказ: в `fill_frac` она не входит,
1734	/// её считает `legs_rejected` (`n_rejected_postonly` в `forms.csv`).
1735	fn rejected_legs<B, MD>(bot: &B, asset_no: usize, entry_id: u64, legs: u8) -> u8
1736	where
