2045	/// `cancel_sent_ns` — часы отправки отмены, по ним работает потолок
2046	/// `CANCEL_WAIT_NS` (F8b, В5/Р2); снятие повторяется на каждом шаге, пока
2047	/// нога, чей запрос постановки был в полёте, не станет снимаемой.
2048	fn on_cancel_pending<MD, B>(
2049	    bot: &mut B,
2050	    state: &mut StrategyState,
2051	    now: i64,
2052	    order_id: u64,
2053	    legs: u8,
2054	    reason: EntryCancelReason,
2055	    cancel_sent_ns: i64,
2056	) -> Result<Action, B::Error>
2057	where
2058	    MD: MarketDepth,
2059	    B: Bot<MD>,
2060	{
2061	    // F8b (В5/Р2): повтор снятия. Нога, чей запрос постановки летел в момент
2062	    // снятия входа, тогда пропущена (`cancel_resting` снимает только `New`/
2063	    // `PartiallyFilled` без запроса в полёте) — без повтора она осталась бы в
2064	    // рынке, а фаза «отмена летит» ждала бы её вечно.
2065	    state.cancel_resting(bot, order_id, legs)?;
2066	    // Исполнение обогнало отмену — позиция есть, ведём её по плану.
2067	    // Пока хоть одна нога ещё стоит или снимается, вход не решён:
2068	    // позицию добираем (F4, В-78), а не бросаем на половине.
2069	    let snap = state.observe_entry(bot, order_id, legs);
2070	    if !snap.open {
2071	        if state.position() > 0.0 {
2072	            state.enter_holding(now);
2073	            return Ok(Action::Idle);
2074	        }
2075	        state.phase = Phase::Idle;
2076	        return Ok(Action::EntryTimedOut { order_id, reason });
2077	    }
2078	    // Потолок ожидания: подтверждение отмены не пришло — круг освобождается
2079	    // под тем же правилом, что и при подтверждённой отмене (позиция есть →
2080	    // ведём её, нет → причина называется). Заявка могла остаться в рынке:
2081	    // это предохранитель, и он назван `CancelTimeout`.
2082	    if now.saturating_sub(cancel_sent_ns) >= CANCEL_WAIT_NS {
2083	        // Ноги остаются сиротами (F8c, К1): снятие повторится на каждом
2084	        // событии, исполнение погасится по рынку и будет посчитано.
2085	        // `observe_entry` выше — по тем же ногам: `entry_qty` и есть их
