2090	            return Ok(Action::Idle);
2091	        }
2092	        state.phase = Phase::Idle;
2093	        return Ok(Action::EntryTimedOut {
2094	            order_id,
2095	            reason: EntryCancelReason::CancelTimeout,
2096	        });
2097	    }
2098	    Ok(Action::Idle)
2099	}
