319	/// Все формы над одними сутками: потоки берут формы по счётчику. `Setups`
320	/// — один проход книги на сутки (`SignalWindows`, общий для форм), дальше у
321	/// каждой формы движок только внутри кругов; `Full` — у каждой формы свой
322	/// `Backtest` над всеми событиями суток (эталон гейта).
323	///
324	/// Память (сервер, 2026-09-18): сигналы формы строятся **в потоке, когда
325	/// форма взята** (например, 48 форм × 100 тыс. касаний × 128 Б заранее — 600 МБ), а
326	/// результат формы отдаётся `sink` сразу и до конца суток не копится
327	/// (`FormOrder`). Возвращает число форм, отданных в `sink`.
328	///
329	/// `approaches` — записи подхода (F6, `--signal approach`): те же сутки и тот
330	/// же порядок, что `touches` (их вид как касания); `None` — сигнал по касаниям.
331	pub(super) fn drive_day(
332	    events: DayRows<'_>,
333	    windows: Option<&SignalWindows>,
334	    touches: &[TouchRecord],
335	    approaches: Option<&[crate::lob::levels::ApproachRecord]>,
336	    forms: &[GridForm],
337	    p: DayParams<'_>,
338	    sink: &mut (dyn FnMut(FormDayResult, &[BounceSignal]) -> anyhow::Result<()> + Send),
339	) -> anyhow::Result<usize> {
340	    // `--driver full` (эталон гейта) держит сутки 64-байтными событиями крейта — одна полная
341	    // развёртка на сутки, общая для форм; путь по окнам (`setups`) разворачивает только круги (Р6).
342	    let expanded: Vec<HbtEvent> = match (windows, events) {
343	        (None, DayRows::Compact(c)) => c.iter().map(CompactEvent::expand).collect(),
344	        _ => Vec::new(),
345	    };
346	    let full: &[HbtEvent] = match (windows, events) {
347	        (None, DayRows::Wide(e)) => e,
348	        _ => &expanded,
349	    };
350	    let next = AtomicUsize::new(0);
351	    let failure: Mutex<Option<anyhow::Error>> = Mutex::new(None);
352	    let order = Mutex::new(FormOrder {
353	        pending: BTreeMap::new(),
354	        next_form: 0,
355	        done: 0,
356	        sink,
357	    });
358	    std::thread::scope(|scope| {
359	        for _ in 0..p.threads.max(1) {
360	            scope.spawn(|| loop {
361	                let i = next.fetch_add(1, Ordering::Relaxed);
362	                if i >= forms.len() {
363	                    break;
364	                }
365	                if failure.lock().map(|f| f.is_some()).unwrap_or(true) {
366	                    break;
367	                }
368	                let cfg = DriveConfig {
369	                    // R2: размер несёт каждый сигнал (`BounceSignal::qty`,
370	                    // `signals_for`); размер прогона сетке не нужен.
371	                    order_qty: 0.0,
372	                    first_order_id: 1,
373	                    queue_model: p.queue_model,
374	                    busy_skip: p.busy_skip,
375	                    hold_skip: p.hold_skip,
376	                };
377	                let step = signals_for(touches, approaches, p.sigma, &forms[i], &p).and_then(
378	                    |(signals, skipped)| {
379	                        let driven = match windows {
380	                            Some(w) => match p.memos {
381	                                // Память формы берёт один поток за раз: форма в наборе одна.
382	                                Some(ms) => {
383	                                    let mut m = ms[p.form_ids[i]]
384	                                        .lock()
385	                                        .unwrap_or_else(std::sync::PoisonError::into_inner);
386	                                    match events {
387	                                        DayRows::Compact(c) => drive_bounce_windowed_memo(
388	                                            c, w, &signals, &cfg, p.rtt_ns, &mut m,
389	                                        ),
390	                                        DayRows::Wide(e) => drive_bounce_windowed_memo(
391	                                            e, w, &signals, &cfg, p.rtt_ns, &mut m,
392	                                        ),
393	                                    }
394	                                }
395	                                None => match events {
396	                                    DayRows::Compact(c) => {
397	                                        drive_bounce_windowed(c, w, &signals, &cfg, p.rtt_ns)
398	                                    }
399	                                    DayRows::Wide(e) => {
400	                                        drive_bounce_windowed(e, w, &signals, &cfg, p.rtt_ns)
401	                                    }
402	                                },
403	                            },
404	                            None => with_backtest_over(
405	                                full,
406	                                p.tick,
407	                                p.lot,
408	                                p.rtt_ns,
409	                                p.queue_model,
410	                                |bt| drive_bounce(bt, 0, &signals, &cfg),
411	                            ),
412	                        };
413	                        driven
414	                            .map(|run| (run, signals, skipped))
415	                            .map_err(|e| anyhow::anyhow!("форма #{i}: {e}"))
416	                    },
417	                );
418	                let flushed = match step {
419	                    Ok((run, signals, skipped)) => match order.lock() {
420	                        Ok(mut o) => {
421	                            o.pending.insert(i, (run, signals, skipped));
422	                            let mut res = Ok(());
423	                            loop {
424	                                let form = o.next_form;
425	                                let Some((run, signals, skipped)) = o.pending.remove(&form) else {
426	                                    break;
427	                                };
428	                                res = (o.sink)(FormDayResult { form, run, skipped }, &signals);
429	                                o.next_form += 1;
430	                                o.done += 1;
431	                                if res.is_err() {
432	                                    break;
433	                                }
434	                            }
435	                            res
436	                        }
437	                        Err(_) => Err(anyhow::anyhow!("результаты форм: мьютекс")),
438	                    },
439	                    Err(e) => Err(e),
440	                };
441	                if let Err(e) = flushed {
442	                    if let Ok(mut f) = failure.lock() {
443	                        if f.is_none() {
444	                            *f = Some(e);
445	                        }
446	                    }
447	                    break;
448	                }
449	            });
450	        }
451	    });
452	    if let Some(e) = failure.into_inner().ok().flatten() {
453	        return Err(e);
454	    }
455	    let o = order
456	        .into_inner()
457	        .map_err(|_| anyhow::anyhow!("результаты форм: мьютекс"))?;
458	    anyhow::ensure!(
459	        o.pending.is_empty(),
460	        "формы без записи в дамп: {}",
461	        o.pending.len()
462	    );
463	    Ok(o.done)
464	}
