1898	fn run_round_group<B, MD>(
1899	    bot: &mut B,
1900	    asset_no: usize,
1901	    entry_state: &mut StrategyState,
1902	    entry_id: u64,
1903	    legs: u8,
1904	    side: HbtSide,
1905	    variant_plans: &[TradePlan],
1906	    variant_next_ids: &[u64],
1907	) -> Result<Vec<(RoundOutcome, f64)>, B::Error>
1908	where
1909	    B: Bot<MD>,
1910	    MD: MarketDepth,
1911	{
1912	    debug_assert_eq!(variant_plans.len(), variant_next_ids.len());
1913	    // --- общий вход: тот же цикл, что у сольного `run_round`, до `Holding` либо до конца круга
1914	    // без входа (таймаут/конец записи) — тогда исход один на всю группу. ---
1915	    let mut timed_out = false;
1916	    let mut cancel_reason = EntryCancelReason::NotPlaced;
1917	    let mut entry_seen: u64 = 0;
1918	    let mut entry_pending: u64 = 0;
1919	    let mut fill_by_cross = false;
1920	    loop {
